Vr[Xr.pid]=Xr.nums
end
for Yr,Zr in pairs(pb.rules(Jr))do
if not Ur[Yr]then
local as={}
for bs,cs in pairs(type(Vr[Yr])==Fqe[2063]and Vr[Yr]or{})do
as[bs]=cs
end
for ds,es in pairs(type(Zr.nums)==Fqe[2063]and Zr.nums or{})do
as[ds]=es
end
local fs=Zr.trigger~=nil and tostring(Zr.trigger):find(Fqe[2468],1,true)~=nil
if Zr.family==Fqe[2247]then
