end
end
if type(as.ampFrom)==Fqe[2063]and tostring(as.ampFrom.kind)==Fqe[1905]and(tonumber(as.ampFrom.amp)or 0)>0 then
local ws=(type(as.secsBy)==Fqe[2063]and#as.secsBy>0)and as.secsBy or{tonumber(as.secsSeen)or tonumber(as.secs)or 5}
