kfb[qfb]=true
end
local rfb,sfb={},0
for tfb,ufb in pairs(ifb.profile_data.collection.owned_units)do
local vfb=N.Units[ufb.unit_id]
local wfb=vfb and ab.FUSE_RANK[vfb.rarity]
if wfb and wfb<=jfb and not kfb[tfb]then
local xfb=ifb.collection:get_unit_by_uuid(tfb)or ufb
if not(ufb._locked or xfb._locked)and not(ufb._equipped_relic or xfb._equipped_relic)then
local yfb,zfb=pcall(N.USC.calculate_xp_gain_from_fuse,hfb,{xfb},ifb)
zfb=yfb and tonumber(zfb)or 0
if zfb>0 then
table.insert(rfb,{uuid=tfb,id=ufb.unit_id,xp=zfb,rarity=vfb.rarity})
sfb=sfb+zfb
end
end
end
end
table.sort(rfb,function(Afb,Bfb)
if Afb.xp~=Bfb.xp then
return Afb.xp<Bfb.xp
end
return Afb.uuid<Bfb.uuid
end)
