local Ohc=W.teamSig()..Fqe[2497]..jb.fxText(Nhc)..(O.killZone~=false and Fqe[3977]or Fqe[982])..(bb.forcedWay()and(Fqe[2497]..bb.forcedWay())or Fqe[982])
local Phc=P.dg.sim[Lhc]
