Phc={none=true,sig=Ohc,at=os.time()}
else
local Vhc=gb.evaluate(Thc,gb.teamFrom(Qhc,Thc.map))
Phc={p=Vhc.p,wave=Vhc.wave,won=Vhc.won,total=Thc.total,margin=Vhc.margin,sig=Ohc,at=os.time(),zone=Thc.zone~=false or nil}
end
P.dg.sim[Lhc]=Phc
if U.count(P.dg.sim)>60 then
local Whc,Xhc
for Yhc,Zhc in pairs(P.dg.sim)do
if not Xhc or(Zhc.at or 0)<Xhc then
Whc,Xhc=Yhc,Zhc.at or 0
end
end
P.dg.sim[Whc]=nil
end
F.saveSoon()
return not Phc.none and Phc or nil
