if not djc or ijc.score>djc.score then
djc=ijc
end
if rjc then
if not gjc or ijc.score>gjc.score then
gjc=ijc
end
elseif not fjc or ijc.score>fjc.score then
fjc=ijc
end
end
if not ejc or ijc.score>ejc.score then
ejc=ijc
end
end
if djc and djc.simLost and fjc then
F.log(1,Fqe[3987],string.format(Fqe[3988],jb.roomName(djc),tostring(djc.sim and djc.sim.margin or Fqe[2299]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(fjc)))
elseif djc and gjc and gjc~=djc and gjc.oldScore>djc.score then
F.log(1,Fqe[3987],string.format(Fqe[3989],jb.roomName(gjc),tostring(gjc.sim and gjc.sim.margin or Fqe[2299]),jb.roomName(djc)))
end
djc=djc or ejc
jb._pick={sig=cjc,x=djc,rooms=Zic}
return djc
end
