end
local cqc=0
for dqc=2,#Ypc do
local eqc,fqc=Ypc[dqc-1],Ypc[dqc]
local gqc=(fqc-eqc).Magnitude
local hqc=math.max(1,math.floor(gqc/2))
for iqc=0,hqc-1 do
local jqc=eqc:Lerp(fqc,iqc/hqc)
table.insert(bb.samples,{pos=jqc,prog=(cqc+gqc*iqc/hqc)/math.max(1,aqc),lane=Wpc.Name})
end
cqc=cqc+gqc
end
if Ypc[#Ypc]then
table.insert(bb.samples,{pos=Ypc[#Ypc],prog=1,lane=Wpc.Name})
end
end
end
