table.insert(Kuc,{p=U.flat(Muc:GetPivot().Position),r=Nuc.range.Value*(V.SUMMONER[Nuc.id.Value]and V.SUMMONER[Nuc.id.Value].reach or 1),air=bb.canAir(Muc)})
