bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(LOc,MOc)
local NOc=bb.bookKey(LOc)
P.layoutRec=type(P.layoutRec)==Fqe[2063]and P.layoutRec or{}
local OOc=P.layoutRec[NOc]
if type(OOc)~=Fqe[2063]then
if not MOc then
return nil
end
OOc={at=os.time()}
P.layoutRec[NOc]=OOc
if U.count(P.layoutRec)>80 then
local POc,QOc
for ROc,SOc in pairs(P.layoutRec)do
local TOc=type(SOc)==Fqe[2063]and tonumber(SOc.at)or 0
if not QOc or TOc<QOc then
POc,QOc=ROc,TOc
end
end
P.layoutRec[POc]=nil
end
end
return OOc
end
function bb.layoutAdd(UOc,VOc,WOc,XOc,YOc)
UOc.runs,UOc.wins=(tonumber(UOc.runs)or 0)+1,(tonumber(UOc.wins)or 0)+(VOc and 1 or 0)
UOc.sec,UOc.wave=type(UOc.sec)==Fqe[2063]and UOc.sec or{},type(UOc.wave)==Fqe[2063]and UOc.wave or{}
if VOc and tonumber(WOc)then
table.insert(UOc.sec,math.floor(WOc+0.5))
end
table.insert(UOc.wave,tonumber(XOc)or 0)
if tonumber(YOc)then
UOc.kills=type(UOc.kills)==Fqe[2063]and UOc.kills or{}
table.insert(UOc.kills,math.floor(tonumber(YOc)))
while#UOc.kills>bb.LAYOUT_KEEP do
table.remove(UOc.kills,1)
end
end
while#UOc.sec>bb.LAYOUT_KEEP do
table.remove(UOc.sec,1)
end
while#UOc.wave>bb.LAYOUT_KEEP do
table.remove(UOc.wave,1)
end
end
function bb.layoutJudge(ZOc,_Oc,aPc,bPc,cPc)
cPc=cPc or Fqe[4317]
local dPc,ePc=tonumber(ZOc and ZOc.runs)or 0,tonumber(_Oc and _Oc.runs)or 0
if dPc<1 or ePc<bb.LAYOUT_CONTROL then
return nil
end
if bPc and type(ZOc.kills)==Fqe[2063]and type(_Oc.kills)==Fqe[2063]and#ZOc.kills>=1 and#_Oc.kills>=bb.LAYOUT_CONTROL then
local fPc,gPc=bb.labMedian(ZOc.kills),bb.labMedian(_Oc.kills)
if fPc and gPc and fPc<gPc*0.97 and(#ZOc.kills>=2 or fPc<gPc*0.85)then
return string.format(Fqe[4318],fPc,gPc,cPc)
end
return nil
end
local hPc,iPc=(tonumber(ZOc.wins)or 0)/dPc,(tonumber(_Oc.wins)or 0)/ePc
if not aPc and iPc>=0.5 then
if hPc+0.25<iPc and(dPc>=2 or(hPc==0 and iPc>=0.9 and ePc>=3))then
return string.format(Fqe[4319],tonumber(ZOc.wins)or 0,dPc,dPc==1 and Fqe[982]or Fqe[1909],tonumber(_Oc.wins)or 0,ePc,cPc)
end
local jPc,kPc=bb.labMedian(ZOc.sec),bb.labMedian(_Oc.sec)
if jPc and kPc and jPc>kPc*1.10 and(#ZOc.sec>=2 or jPc>kPc*1.25)then
return string.format(Fqe[4320],math.floor(jPc/60),jPc%60,math.floor(kPc/60),kPc%60,cPc)
end
return nil
end
local lPc,mPc=bb.labMedian(ZOc.wave),bb.labMedian(_Oc.wave)
if lPc and mPc and lPc<mPc-math.max(1,mPc*0.03)and(dPc>=2 or lPc<mPc*0.85)then
return string.format(Fqe[4321],lPc,mPc,cPc)
end
return nil
end
function bb.layoutResult(nPc,oPc)
local pPc=bb.info
local qPc=bb.layoutSrc
if not(pPc and qPc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not pPc.timeLimit then
return
end
local rPc=bb.wave()
local sPc=bb.layoutRecFor(pPc,true)
sPc.at=os.time()
local tPc=pPc.timeLimit~=nil
local uPc=pPc.killScore and true or nil
local vPc=uPc and(bb.killsEnd or bb.realKills())or nil
if qPc==Fqe[4287]then
local wPc=bb.bookFor(pPc)
if not wPc then
return
end
wPc.real=type(wPc.real)==Fqe[2063]and wPc.real or{}
bb.layoutAdd(wPc.real,nPc,oPc,rPc,vPc)
local xPc=wPc.aside==nil and bb.layoutJudge(wPc.real,sPc.own,tPc,uPc)or nil
if xPc then
wPc.aside={at=os.time(),why=xPc}
F.log(1,Fqe[4223],string.format(Fqe[4322],xPc))
end
elseif qPc==Fqe[3656]then
sPc.hiveUnit=type(sPc.hiveUnit)==Fqe[2063]and sPc.hiveUnit or{}
local yPc=sPc.hiveUnit
bb.layoutAdd(yPc,nPc,oPc,rPc,vPc)
local zPc=bb.bookFor(pPc)
local APc=zPc and type(zPc.real)==Fqe[2063]and(tonumber(zPc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local BPc=APc and zPc.real or sPc.own
local CPc=bb.layoutJudge(yPc,BPc,tPc,uPc,APc and Fqe[4323]or nil)
if CPc then
yPc.aside,yPc.why=os.time(),CPc
F.log(1,Fqe[4223],string.format(Fqe[4324],CPc))
elseif(tonumber(yPc.runs)or 0)>=bb.HIVE_TRIALS then
local DPc=BPc and bb.layoutJudge(BPc,yPc,tPc,uPc,Fqe[4325])
if DPc and zPc and type(bb.hiveUnitPlan)==Fqe[2063]then
for EPc,FPc in pairs(bb.hiveUnitPlan)do
zPc.spots[EPc]=FPc
end
zPc.real={runs=yPc.runs,wins=yPc.wins,sec=yPc.sec,wave=yPc.wave,kills=yPc.kills}
zPc.hive,zPc.aside=os.time(),nil
sPc.hiveUnit=nil
F.log(1,Fqe[4223],string.format(Fqe[4326],DPc))
else
yPc.aside,yPc.why=os.time(),Fqe[4327]
F.log(1,Fqe[4223],Fqe[4328])
end
end
else
sPc[qPc]=type(sPc[qPc])==Fqe[2063]and sPc[qPc]or{}
local GPc=sPc[qPc]
bb.layoutAdd(GPc,nPc,oPc,rPc,vPc)
if qPc==Fqe[3655]and GPc.aside==nil then
local HPc=bb.layoutJudge(GPc,sPc.own,tPc,uPc)
if HPc then
GPc.aside,GPc.why=os.time(),HPc
F.log(1,Fqe[4223],string.format(Fqe[4329],HPc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={Fqe[4330],Fqe[4331],Fqe[4332],Fqe[4333]}
function bb.controlSpot(IPc,JPc)
if not bb.killZone()then
return nil
end
local KPc=gb.holds
if not KPc(IPc.id)or V.toggleOf(IPc.id)then
return nil
end
local LPc,MPc,NPc,OPc=1,0,0,{}
local PPc=bb.hurtSamples()
for QPc,RPc in ipairs(bb.mine or{})do
local SPc=RPc._stats
local TPc=SPc.id.Value
if SPc:FindFirstChild(Fqe[2316])and not V.isFarm(TPc)and not V.allyBuff(TPc)then
local UPc,VPc=U.flat(RPc:GetPivot().Position),SPc.range.Value
if KPc(TPc)and not V.toggleOf(TPc)then
NPc=NPc+1
table.insert(OPc,{p=UPc,r=VPc})
else
for WPc,XPc in ipairs(PPc)do
if(U.flat(XPc.pos)-UPc).Magnitude<=VPc then
LPc,MPc=math.min(LPc,XPc.prog),math.max(MPc,XPc.prog)
end
end
end
end
end
if MPc<=LPc then
LPc,MPc=0.75,0.98
end
local YPc=(JPc or NPc)+1
local ZPc=({LPc,MPc,(LPc+MPc)/2,LPc-(MPc-LPc)/2})[YPc]
if not ZPc then
return nil
end
local _Pc=V.range(IPc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local aQc={}
for bQc,cQc in ipairs(bb.cands)do
local dQc,eQc,fQc=U.flat(cQc),0,0
for gQc,hQc in ipairs(PPc)do
if(U.flat(hQc.pos)-dQc).Magnitude<=_Pc then
fQc=fQc+1
if math.abs(hQc.prog-ZPc)<=0.05 then
eQc=eQc+1
local iQc=U.flat(hQc.pos)
for jQc,kQc in ipairs(OPc)do
if(iQc-kQc.p).Magnitude<=kQc.r then
eQc=eQc-0.5
break
end
end
end
end
end
if eQc>0 then
table.insert(aQc,{pos=cQc,sc=eQc,cov=fQc})
end
if bQc%60==0 then
task.wait()
end
end
table.sort(aQc,function(lQc,mQc)
return lQc.sc>mQc.sc
end)
for nQc,oQc in ipairs(aQc)do
local pQc=bb.valid(oQc.pos,IPc.data)
if pQc then
F.log(1,Fqe[4162],string.format(Fqe[4334],V.name(IPc.id),bb.CONTROL_WORDS[YPc],math.floor(ZPc*100+0.5)))
return pQc,oQc.cov,ZPc
end
if nQc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(qQc)
local rQc,sQc=gb.holds(qQc.id)
if not rQc then
return nil
end
if V.killFed(qQc.id)then
return nil
end
local tQc,uQc={},0
for vQc,wQc in ipairs(bb.mine or{})do
local xQc=wQc._stats
local yQc=xQc.id.Value
if xQc:FindFirstChild(Fqe[2316])and not V.isFarm(yQc)and not V.allyBuff(yQc)and yQc~=qQc.id then
local zQc,AQc=pcall(bb.liveDps,wQc,yQc)
AQc=zQc and tonumber(AQc)or 0
if AQc>0 then
table.insert(tQc,{p=U.flat(wQc:GetPivot().Position),r=xQc.range.Value,d=AQc})
uQc=uQc+AQc
end
end
end
if#tQc==0 or uQc<=0 then
return nil
end
local BQc=bb.hurtSamples()
local CQc={}
for DQc,EQc in ipairs(BQc)do
local FQc,GQc=U.flat(EQc.pos),0
for HQc,IQc in ipairs(tQc)do
if(FQc-IQc.p).Magnitude<=IQc.r then
GQc=GQc+IQc.d
end
end
CQc[DQc]=GQc/uQc
end
local JQc=V.range(qQc.u,math.min(tonumber(sQc)or 0,3,V.rows(qQc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local KQc,LQc,MQc
for NQc,OQc in ipairs(bb.cands)do
local PQc,QQc,RQc=U.flat(OQc),0,0
for SQc,TQc in ipairs(BQc)do
if(U.flat(TQc.pos)-PQc).Magnitude<=JQc then
QQc=QQc+CQc[SQc]
RQc=RQc+1
end
end
if QQc>0 and(not LQc or QQc>LQc)then
local UQc=bb.valid(OQc,qQc.data)
if UQc then
KQc,LQc,MQc=UQc,QQc,RQc
end
end
if NQc%40==0 then
task.wait()
end
end
if not KQc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[qQc.id]then
bb.holdSaid[qQc.id]=true
F.log(1,Fqe[4162],string.format(Fqe[4335],V.name(qQc.id)))
end
return KQc,MQc or 0
end
