bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(zhd,Ahd)
local Bhd=(Ahd.t or 0)-(zhd.t or 0)
if Bhd<bb.BASE_WIN-1 then
return false
end
local Chd=((tonumber(zhd.base)or 0)-(tonumber(Ahd.base)or 0))/Bhd
if Chd<=0 or(tonumber(Ahd.base)or 0)<=0 then
return false
end
local Dhd=Ahd.base/Chd
local Ehd,Fhd=0,0
local Ghd,Hhd=zhd.foes or{},Ahd.foes or{}
for Ihd,Jhd in pairs(Hhd)do
if Jhd.prog>=bb.BASE_END then
Ehd=Ehd+Jhd.hp
local Khd=Ghd[Ihd]
if Khd then
Fhd=Fhd+math.max(0,Khd.hp-Jhd.hp)
end
end
end
for Lhd,Mhd in pairs(Ghd)do
if Mhd.prog>=bb.BASE_END and not Hhd[Lhd]then
Fhd=Fhd+Mhd.hp
end
end
if Ehd<=0 then
return false
end
local Nhd=Fhd/Bhd
local Ohd=Nhd>0 and Ehd/Nhd or math.huge
local Phd={baseTime=Dhd,loss=Chd,atEnd=Ehd,rate=Nhd,killTime=Ohd}
return Dhd<bb.BASE_SOON and Ohd>Dhd*bb.BASE_MARGIN,Phd
end
