function bb.leakAhead(rid)
local sid=0
local tid=U.flat(rid.pos)
for vid,wid in ipairs(bb.mine or{})do
local xid=wid:FindFirstChild(Fqe[2127])
local yid=xid and xid:FindFirstChild(Fqe[2441])
