if yid and zid and not V.isFarm(yid.Value)and not V.allyBuff(yid.Value)then
local Aid,Bid=U.flat(wid:GetPivot().Position),zid.Value
if(not rid.fly or bb.canAir(wid))and(Aid-tid).Magnitude>Bid then
for Cid,Did in ipairs(bb.samples or{})do
if Did.prog>rid.prog and(U.flat(Did.pos)-Aid).Magnitude<=Bid then
sid=sid+1
break
end
end
end
end
end
return sid
