return
end
local Gid=workspace:FindFirstChild(Fqe[4634])and workspace._BASES:FindFirstChild(Fqe[4123])
local Hid=Gid and Gid:FindFirstChild(Fqe[4355])and Gid.base:FindFirstChild(Fqe[4356])
local Iid=Hid and Hid:FindFirstChildOfClass(Fqe[2459])
if not Iid or Iid.Health<=0 then
return
end
local Jid=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local Kid=U.now()
bb.leakTrack=bb.leakTrack or{}
local Lid=bb.leakTrack
local Mid,Nid={},nil
for Oid,Pid in ipairs(bb.enemies or{})do
if Pid.m then
Mid[Pid.m]=true
local Qid,Rid=tonumber(Pid.hp)or 0,tonumber(Pid.prog)or 0
local Sid=Lid[Pid.m]
if not Sid then
Lid[Pid.m]={t=Kid,hp=Qid,prog=Rid}
else
if Kid-Sid.t>=bb.LEAK_WIN then
Sid.pace,Sid.net=(Rid-Sid.prog)/(Kid-Sid.t),(Sid.hp-Qid)/(Kid-Sid.t)
Sid.t,Sid.hp,Sid.prog=Kid,Qid,Rid
end
if Sid.pace and Sid.pace>0 and Qid>0 then
