end
bb.bailNote(Fid,Fqe[4628])
F.log(1,Fqe[2732],string.format(Fqe[4636],bb.wave(),tonumber(bb.total)or 0,math.floor(Nid.left+0.5),U.fmt(Nid.hp),U.fmt(Nid.arriving),U.fmt(Nid.net),Nid.baseTime))
pcall(F.saveNow)
F.request(Fqe[2135],Fqe[4171])
