local gjd=tonumber(ejd.range.Value)or 0
local hjd=bb.coverMax[djd]
if not(hjd and hjd.r==gjd)then
local ijd,jjd=U.flat(djd:GetPivot().Position),-1
for kjd,ljd in ipairs(bb.samples or{})do
if ljd.prog>jjd and(U.flat(ljd.pos)-ijd).Magnitude<=gjd then
jjd=ljd.prog
end
end
hjd={r=gjd,far=jjd}
bb.coverMax[djd]=hjd
end
table.insert(bjd,{far=hjd.far,air=bb.canAir(djd)})
end
end
if#bjd==0 then
